srcDoc.css:
* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  background: #f7f9fc;
  color: #18212f;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 14px;
}

button,
select {
  font: inherit;
}

.analysis-app {
  width: 100%;
  min-height: 100vh;
  background: linear-gradient(180deg, #ffffff 0, #ffffff 160px, #f7f9fc 160px, #f7f9fc 100%);
}

.analysis-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  width: 100%;
  padding: 26px 30px 24px;
  background: #ffffff;
  border-bottom: 1px solid #e6ebf2;
}

.header-copy {
  min-width: 260px;
  max-width: 720px;
}

.eyebrow,
.section-kicker {
  display: block;
  margin: 0 0 7px;
  color: #138bc5;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.header-copy h1 {
  margin: 0;
  color: #18212f;
  font-size: clamp(28px, 2.4vw, 38px);
  line-height: 1.1;
  font-weight: 760;
  letter-spacing: -0.035em;
}

.header-copy p {
  margin: 10px 0 0;
  color: #687486;
  font-size: 14px;
  line-height: 1.55;
}

.header-controls {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 128px;
}

.control-group label {
  color: #6d7889;
  font-size: 11px;
  line-height: 1;
  font-weight: 750;
  letter-spacing: 0.045em;
  text-transform: uppercase;
}

.control-group select,
.query-display {
  height: 42px;
  padding: 0 34px 0 12px;
  color: #243044;
  background-color: #ffffff;
  border: 1px solid #dce3ec;
  border-radius: 9px;
  font-size: 13px;
  line-height: 40px;
  font-weight: 600;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
}

.control-group select {
  cursor: pointer;
}

.control-group select:hover,
.control-group select:focus {
  border-color: #83c5e7;
}

.control-group select:focus {
  box-shadow: 0 0 0 3px rgba(19, 139, 197, 0.1);
}

.query-control {
  min-width: 210px;
}

.query-display {
  overflow: hidden;
  max-width: 250px;
  padding-right: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
  background: #f9fbfd;
}

.refresh-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  padding: 0;
  color: #168fc7;
  background: #eef8fc;
  border: 1px solid #d4edf8;
  border-radius: 9px;
  font-size: 23px;
  line-height: 1;
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
}

.refresh-button:hover {
  background: #e3f4fb;
  border-color: #bfe4f4;
}

.refresh-button:active {
  transform: rotate(30deg);
}

.analysis-content {
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 24px 30px 32px;
}

.analysis-body {
  display: flex;
  flex-direction: column;
  gap: 24px;
  width: 100%;
}

.hidden {
  display: none !important;
}

.system-state {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 64px;
  padding: 16px 18px;
  color: #526074;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  font-size: 14px;
}

.loading-dot {
  width: 9px;
  height: 9px;
  background: #17a1d4;
  border-radius: 50%;
  animation: loadingPulse 1.1s ease-in-out infinite;
}

@keyframes loadingPulse {
  0%, 100% {
    opacity: 0.35;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}
.error-state {
  align-items: flex-start;
  flex-direction: column;
  gap: 4px;
  color: #9f2f3e;
  background: #fff7f8;
  border-color: #f0d4d9;
}

.empty-state {
  align-items: flex-start;
  flex-direction: column;
  gap: 4px;
}

section {
  width: 100%;
}

.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 15px;
}

.section-heading h2 {
  margin: 0;
  color: #202b3a;
  font-size: 20px;
  line-height: 1.25;
  font-weight: 740;
  letter-spacing: -0.015em;
}

.section-description {
  margin: 6px 0 0;
  color: #778396;
  font-size: 13px;
  line-height: 1.5;
}

.comparison-badge {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 7px 11px;
  color: #536174;
  background: #ffffff;
  border: 1px solid #dfe6ee;
  border-radius: 999px;
  font-size: 12px;
  line-height: 1;
  font-weight: 650;
  white-space: nowrap;
}

.status-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(420px, 1fr);
  gap: 14px;
  width: 100%;
}

.status-main-card,
.mini-kpi,
.insight-card,
.platform-card,
.format-card,
.evidence-card,
.action-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.025), 0 4px 14px rgba(16, 24, 40, 0.025);
}

.status-main-card {
  min-height: 214px;
  padding: 22px 24px;
  border-radius: 14px;
}

.status-main-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.card-label {
  display: block;
  color: #7b8798;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: 0.055em;
}

.status-value {
  margin-top: 7px;
  color: #152235;
  font-size: clamp(38px, 4vw, 52px);
  line-height: 1;
  font-weight: 770;
  letter-spacing: -0.045em;
}

.trend-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 80px;
  min-height: 34px;
  padding: 8px 11px;
  border-radius: 999px;
  font-size: 13px;
  line-height: 1;
  font-weight: 760;
}

.trend-pill.positive {
  color: #167b5b;
  background: #eaf8f3;
}

.trend-pill.negative {
  color: #b24452;
  background: #fff0f2;
}

.trend-pill.neutral {
  color: #667386;
  background: #f0f3f7;
}

.status-main-card h3 {
  margin: 22px 0 8px;
  color: #263347;
  font-size: 19px;
  line-height: 1.35;
  font-weight: 720;
}

.status-main-card p {
  max-width: 820px;
  margin: 0;
  color: #667386;
  font-size: 14px;
  line-height: 1.6;
}

.status-period-note {
  margin-top: 18px;
  color: #8792a2;
  font-size: 12px;
}

.status-period-note strong {
  color: #526074;
}

.status-kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.mini-kpi {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 104px;
  padding: 16px 17px;
  border-radius: 12px;
}

.mini-kpi-label {
  color: #7d8899;
  font-size: 11px;
  line-height: 1.3;
  font-weight: 700;
}

.mini-kpi strong {
  margin-top: 7px;
  color: #233044;
  font-size: 27px;
  line-height: 1;
  font-weight: 760;
  letter-spacing: -0.03em;
}

.mini-kpi-change {
  margin-top: 7px;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 650;
}

.mini-kpi-change.positive {
  color: #17805f;
}

.mini-kpi-change.negative {
  color: #b24553;
}

.mini-kpi-change.neutral,
.mini-kpi-change.muted {
  color: #8a95a4;
}

.insight-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 14px;
  width: 100%;
}

.insight-card {
  width: 100%;
  min-height: 0;
  padding: 20px 21px;
  border-radius: 14px;
}

.positive-card {
  border-top: 3px solid #3bb28a;
}

.warning-card {
  border-top: 3px solid #efb24e;
}

.insight-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.insight-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  color: #198761;
  background: #edf9f4;
  border-radius: 9px;
  font-size: 16px;
  font-weight: 800;
}

.warning-card .insight-icon {
  color: #a16b17;
  background: #fff7e9;
}

.insight-card-header h3 {
  margin: 4px 0 0;
  color: #263347;
  font-size: 16px;
  line-height: 1.3;
  font-weight: 720;
}

.insight-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.insight-item {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  align-items: start;
  gap: 11px;
  padding: 11px 0;
  border-top: 1px solid #edf0f4;
}

.insight-item:first-child {
  padding-top: 0;
  border-top: 0;
}

.insight-bullet {
  width: 6px;
  height: 6px;
  margin-top: 7px;
  background: #2fa77f;
  border-radius: 50%;
}

.warning-card .insight-bullet {
  background: #e2a13d;
}

.insight-copy strong {
  display: block;
  color: #344054;
  font-size: 13px;
  line-height: 1.4;
  font-weight: 700;
}

.insight-copy span {
  display: block;
  margin-top: 4px;
  color: #7a8697;
  font-size: 12px;
  line-height: 1.5;
}

.insight-metric {
  color: #526074;
  font-size: 12px;
  line-height: 1.4;
  font-weight: 750;
  white-space: nowrap;
}

.actions-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 12px;
  width: 100%;
}

.action-card {
  position: relative;
  min-height: 184px;
  padding: 19px;
  overflow: hidden;
  border-radius: 13px;
}

.action-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 29px;
  height: 29px;
  color: #ffffff;
  background: #168fc7;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
}

.action-card h3 {
  margin: 15px 0 8px;
  color: #253246;
  font-size: 15px;
  line-height: 1.4;
  font-weight: 730;
}

.action-card p {
  margin: 0;
  color: #6f7b8c;
  font-size: 12px;
  line-height: 1.6;
}

.action-evidence {
  margin-top: 14px;
  padding-top: 11px;
  color: #657285;
  border-top: 1px solid #edf0f4;
  font-size: 11px;
  line-height: 1.45;
}

.action-evidence strong {
  color: #324056;
}

.platform-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  width: 100%;
}

.platform-card {
  padding: 18px;
  border-radius: 13px;
}

.platform-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 17px;
}

.platform-name {
  color: #29364a;
  font-size: 15px;
  font-weight: 750;
  text-transform: capitalize;
}

.platform-rank {
  display: inline-flex;
  align-items: center;
  padding: 5px 8px;
  color: #607085;
  background: #f2f5f8;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 750;
}

.platform-primary {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-bottom: 8px;
}

.platform-primary strong {
  color: #202d41;
  font-size: 30px;
  line-height: 1;
  font-weight: 770;
  letter-spacing: -0.035em;
}

.platform-primary span {
  color: #8490a0;
  font-size: 11px;
}

.platform-change {
  margin-bottom: 15px;
  font-size: 12px;
  font-weight: 700;
}

.platform-change.positive {
  color: #18805f;
}

.platform-change.negative {
  color: #b34a56;
}

.platform-change.neutral {
  color: #8390a1;
}

.platform-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding-top: 13px;
  border-top: 1px solid #edf0f4;
}

.platform-meta div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.platform-meta span {
  color: #909aaa;
  font-size: 10px;
}

.platform-meta strong {
  color: #526074;
  font-size: 12px;
  font-weight: 700;
}

.format-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  width: 100%;
}

.format-card {
  padding: 17px;
  border-radius: 13px;
}

.format-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 13px;
}

.format-name {
  color: #273449;
  font-size: 14px;
  font-weight: 750;
  text-transform: capitalize;
}

.format-platform {
  padding: 5px 8px;
  color: #667589;
  background: #f2f5f8;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 650;
  text-transform: capitalize;
}

.format-value {
  color: #223046;
  font-size: 27px;
  line-height: 1;
  font-weight: 760;
  letter-spacing: -0.03em;
}

.format-caption {
  display: block;
  margin-top: 5px;
  color: #8b96a6;
  font-size: 10px;
}

.format-bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
  padding-top: 11px;
  border-top: 1px solid #edf0f4;
}

.format-share,
.format-trend {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.format-share span,
.format-trend span {
  color: #929cac;
  font-size: 10px;
}

.format-share strong,
.format-trend strong {
  color: #536175;
  font-size: 12px;
}

.evidence-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  width: 100%;
}

.evidence-card {
  display: flex;
  flex-direction: column;
  min-height: 240px;
  padding: 18px;
  border-radius: 13px;
}

.evidence-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
  margin-bottom: 12px;
}

.evidence-platform {
  color: #1b83b5;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.evidence-rank {
  color: #8994a4;
  font-size: 10px;
  font-weight: 700;
}

.evidence-format {
  display: inline-flex;
  align-self: flex-start;
  margin-bottom: 10px;
  padding: 5px 8px;
  color: #5f6e82;
  background: #f2f5f8;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 650;
  text-transform: capitalize;
}

.evidence-copy {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: #48566a;
  font-size: 12px;
  line-height: 1.55;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
}

.evidence-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: auto;
  padding-top: 16px;
}

.evidence-metric {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 9px;
  background: #f8fafc;
  border-radius: 8px;
}

.evidence-metric span {
  color: #929cac;
  font-size: 9px;
}

.evidence-metric strong {
  color: #3b495e;
  font-size: 12px;
  font-weight: 750;
}

.evidence-link {
  display: inline-flex;
  margin-top: 12px;
  color: #158dc4;
  font-size: 11px;
  line-height: 1;
  font-weight: 700;
  text-decoration: none;
}

.evidence-link:hover {
  text-decoration: underline;
}

.analysis-footer {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-top: 2px;
  padding: 16px 2px 0;
  border-top: 1px solid #e3e8ef;
}

.methodology-note {
  max-width: 960px;
  color: #8a95a5;
  font-size: 10px;
  line-height: 1.55;
}

.methodology-note strong {
  color: #697689;
}

.generated-at {
  color: #929cab;
  font-size: 10px;
  white-space: nowrap;
}

@media (max-width: 1180px) {
  .analysis-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .header-controls {
    justify-content: flex-start;
    width: 100%;
  }
  .status-grid {
    grid-template-columns: 1fr;
  }
  .actions-list,
  .platform-grid,
  .format-grid,
  .evidence-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .analysis-header,
  .analysis-content {
    padding-left: 18px;
    padding-right: 18px;
  }
  .header-controls {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .control-group,
  .query-control {
    min-width: 0;
  }
  .query-display {
    max-width: none;
  }
  .refresh-button {
    width: 100%;
  }
  .status-kpis,
  .insight-grid,
  .actions-list,
  .platform-grid,
  .format-grid,
  .evidence-grid {
    grid-template-columns: 1fr;
  }
  .section-heading {
    align-items: flex-start;
    flex-direction: column;
  }
  .analysis-footer {
    flex-direction: column;
    gap: 8px;
  }
}
@media (max-width: 480px) {
  .header-controls {
    grid-template-columns: 1fr;
  }
  .analysis-header {
    padding-top: 20px;
  }
  .analysis-content {
    padding-top: 18px;
  }
  .status-main-card,
  .insight-card {
    padding: 16px;
  }
  .status-main-top {
    flex-direction: column;
  }
  .trend-pill {
    align-self: flex-start;
  }
}

