  font-size: 10px;

  white-space: nowrap;
}

@media (max-width: 1180px) {
  .analysis-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .header-controls {
    justify-content: flex-start;

    width: 100%;
  }

  .status-grid {
    grid-template-columns: 1fr;
  }

  .actions-list,
  .platform-grid,
  .format-grid,
  .evidence-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }
}

@media (max-width: 760px) {
  .analysis-header,
  .analysis-content {
    padding-left: 18px;
    padding-right: 18px;
  }

  .header-controls {
    display: grid;

    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .control-group,
  .query-control {
    min-width: 0;
  }

  .query-display {
    max-width: none;
  }

  .refresh-button {
    width: 100%;
  }

  .status-kpis,
  .insight-grid,
  .actions-list,
  .platform-grid,
  .format-grid,
  .evidence-grid {
    grid-template-columns: 1fr;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .analysis-footer {
    flex-direction: column;

    gap: 8px;
  }
}

@media (max-width: 480px) {
  .header-controls {
    grid-template-columns: 1fr;
  }

  .analysis-header {
    padding-top: 20px;
  }

  .analysis-content {
    padding-top: 18px;
  }

  .status-main-card,
  .insight-card {
    padding: 16px;
  }

  .status-main-top {
    flex-direction: column;
  }

  .trend-pill {
    align-self: flex-start;
  }
}

