appsmith.onReady(function () {

  var initialized = false;


  function byId(id) {
    return document.getElementById(id);
  }


  function escapeHtml(value) {
    return String(
      value === null ||
      value === undefined
        ? ''
        : value
    )
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }


  function toNumber(value) {
    var number =
      Number(value);

    return Number.isFinite(number)
      ? number
      : null;
  }


  function formatNumber(
    value,
    maximumFractionDigits
  ) {
    var number =
      toNumber(value);

    if (number === null) {
      return '—';
    }

    return new Intl.NumberFormat(
      'es-MX',
      {
        maximumFractionDigits:
          maximumFractionDigits === undefined
            ? 2
            : maximumFractionDigits
      }
    ).format(number);
  }


  function formatInteger(value) {
    var number =
      toNumber(value);

    if (number === null) {
      return '—';
    }

    return new Intl.NumberFormat(
      'es-MX',
      {
        maximumFractionDigits: 0
      }
    ).format(number);
  }


  function formatPct(value) {
    var number =
      toNumber(value);

    if (number === null) {
      return '—';
    }

    var prefix =
      number > 0
        ? '+'
        : '';

    return (
      prefix +
      formatNumber(
        number,
        2
      ) +
      '%'
    );
  }


  function trendClass(value) {
    var number =
      toNumber(value);

    if (number === null) {
      return 'neutral';
    }

    if (number > 0) {
      return 'positive';
    }

    if (number < 0) {
      return 'negative';
    }

    return 'neutral';
  }


  function platformLabel(value) {
    var map = {
      facebook: 'Facebook',
      instagram: 'Instagram',
      tiktok: 'TikTok',
      threads: 'Threads',
      all: 'Todas'
    };

    return (
      map[
        String(value || '')
          .toLowerCase()
      ] ||
      String(value || '')
    );
  }


  function formatLabel(value) {
    var map = {
      video: 'Video',
      carousel: 'Carrusel',
      image: 'Imagen',
      sin_clasificar: 'Sin clasificar'
    };

    return (
      map[
        String(value || '')
          .toLowerCase()
      ] ||
      String(value || '')
    );
  }


  function shortText(
    value,
    maxLength
  ) {
    var text =
      String(value || '')
        .replace(/\s+/g, ' ')
        .trim();

    if (
      text.length <=
      maxLength
    ) {
      return text;
    }

    return (
      text.slice(
        0,
        maxLength - 1
      ).trim() +
      '…'
    );
  }


  function getRuntime(model) {
    var runtime =
      model &&
      model.runtime
        ? model.runtime
        : {};

    return {
      queries:
        Array.isArray(
          runtime.queries
        )
          ? runtime.queries
          : [],

      estado:
        runtime.estado || null,

      palancas:
        Array.isArray(
          runtime.palancas
        )
          ? runtime.palancas
          : [],

      formatos:
        Array.isArray(
          runtime.formatos
        )
          ? runtime.formatos
          : [],

      evidencias:
        Array.isArray(
          runtime.evidencias
        )
          ? runtime.evidencias
          : [],

      meta:
        runtime.meta || {
          loading: true,
          empty: false,
          error: '',
          generatedAt: null
        }
    };
  }


  function getQueries(model) {
    if (
      model &&
      Array.isArray(
        model.queries
      ) &&
      model.queries.length > 0
    ) {
      return model.queries;
    }

    return getRuntime(model).queries;
  }


  function findOverall(rows) {
    if (!Array.isArray(rows)) {
      return null;
    }

    for (
      var i = 0;
      i < rows.length;
      i++
    ) {
      if (
        String(
          rows[i].platform || ''
        ).toLowerCase() ===
        'all'
      ) {
        return rows[i];
      }
    }

    return null;
  }


  function getPlatformRows(rows) {
    return (
      Array.isArray(rows)
        ? rows.filter(
            function (row) {
              return (
                String(
                  row.platform || ''
                ).toLowerCase() !==
                'all'
              );
            }
          )
        : []
    );
  }


  function setText(
    id,
    value
  ) {
    var element =
      byId(id);

    if (!element) {
      return;
    }

    element.textContent =
      value === null ||
      value === undefined ||
      value === ''
        ? '—'
        : String(value);
  }


  function setTrend(
    id,
    value
  ) {
    var element =
      byId(id);

    if (!element) {
      return;
    }

    var className =
      trendClass(value);

    element.className =
      (
        id ===
        'engagementTrend'
      )
        ? (
            'trend-pill ' +
            className
          )
        : (
            'mini-kpi-change ' +
            className
          );

    element.textContent =
      formatPct(value);
  }


  function setLoading() {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.remove(
        'hidden'
      );
    }

    if (error) {
      error.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.add(
        'hidden'
      );
    }
  }


  function setError(message) {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.add(
        'hidden'
      );
    }

    if (error) {
      error.classList.remove(
        'hidden'
      );
    }

    setText(
      'errorMessage',
      message
    );
  }


  function setEmpty() {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.add(
        'hidden'
      );
    }

    if (error) {
      error.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.remove(
        'hidden'
      );
    }
  }


  function setReady() {
    var loading =
      byId('loadingState');

    var error =
      byId('errorState');

    var empty =
      byId('emptyState');

    var body =
      byId('analysisBody');

    if (loading) {
      loading.classList.add(
        'hidden'
      );
    }

    if (error) {
      error.classList.add(
        'hidden'
      );
    }

    if (empty) {
      empty.classList.add(
        'hidden'
      );
    }

    if (body) {
      body.classList.remove(
        'hidden'
      );
    }
  }


  function renderQuerySelect(model) {
    var select =
      byId('querySelect');

    if (!select) {
      return;
    }

    var queries =
      getQueries(model);

    if (
      !Array.isArray(queries) ||
      queries.length === 0
    ) {
      return;
    }

    var selectedQueryId =
      String(
        model &&
        model.selectedQueryId
          ? model.selectedQueryId
          : ''
      ).trim();

    select.innerHTML =
      queries
        .map(function (query) {
          var id =
            String(
              query &&
              query.id
                ? query.id
                : ''
            ).trim();

          var name =
            String(
              query &&
              query.name
                ? query.name
                : ''
            ).trim();

          return (
            '<option value="' +
              escapeHtml(id) +
            '">' +
              escapeHtml(name) +
            '</option>'
          );
        })
        .join('');

    var selectedExists =
      queries.some(
        function (query) {
          return (
            String(
              query &&
              query.id
                ? query.id
                : ''
            ).trim() ===
            selectedQueryId
          );
        }
      );

    if (selectedExists) {
      select.value =
        selectedQueryId;

    } else if (
      queries.length > 0
    ) {
      select.value =
        String(
          queries[0].id || ''
        );
    }
  }


  function buildStatus(
    overall,
    platformRows
  ) {
    if (!overall) {
      return;
    }

    var current =
      toNumber(
        overall
          .current_engagement_per_post
      );

    var previous =
      toNumber(
        overall
          .previous_engagement_per_post
      );

    var change =
      toNumber(
        overall
          .engagement_per_post_change_pct
      );

    var days =
      toNumber(
        overall.comparison_days
      );

    setText(
      'engagementValue',
      formatNumber(
        current,
        2
      )
    );

    setTrend(
      'engagementTrend',
      change
    );

    setText(
      'currentPosts',
      formatInteger(
        overall.current_posts
      )
    );

    setTrend(
      'postsTrend',
      overall
        .publishing_change_pct
    );

    setText(
      'likesPerPost',
      formatNumber(
        overall
          .current_likes_per_post,
        2
      )
    );

    setTrend(
      'likesTrend',
      overall
        .likes_per_post_change_pct
    );

    setText(
      'commentsPerPost',
      formatNumber(
        overall
          .current_comments_per_post,
        2
      )
    );

    setTrend(
      'commentsTrend',
      overall
        .comments_per_post_change_pct
    );

    var comparablePlatforms =
      platformRows.filter(
        function (row) {
          return (
            toNumber(
              row.current_posts
            ) > 0 &&
            toNumber(
              row.previous_posts
            ) > 0
          );
        }
      ).length;

    setText(
      'comparablePlatforms',
      comparablePlatforms
    );

    if (days !== null) {
      setText(
        'comparisonBadge',
        (
          days +
          ' días vs ' +
          days +
          ' días'
        )
      );

      setText(
        'comparisonPeriod',
        (
          'últimos ' +
          days +
          ' días frente a los ' +
          days +
          ' días anteriores'
        )
      );

    } else {
      setText(
        'comparisonBadge',
        'Sin ventana comparable'
      );

      setText(
        'comparisonPeriod',
        'sin histórico comparable'
      );
    }

    var headline =
      'El engagement se mantiene sin un cambio concluyente';

    if (
      change !== null &&
      change <= -5
    ) {
      headline =
        'El engagement por publicación está por debajo de la ventana anterior';

    } else if (
      change !== null &&
      change >= 5
    ) {
      headline =
        'El engagement por publicación está por encima de la ventana anterior';
    }

    setText(
      'statusHeadline',
      headline
    );

    var explanation =
      'Aún no existe una comparación suficiente para describir la variación reciente.';

    if (
      current !== null &&
      previous !== null
    ) {
      explanation =
        (
          'Cada publicación registra ' +
          formatNumber(
            current,
            2
          ) +
          ' likes + comentarios, frente a ' +
          formatNumber(
            previous,
            2
          ) +
          ' en la ventana anterior.'
        );
    }

    setText(
      'statusExplanation',
      explanation
    );
  }


  function insightItem(
    title,
    description,
    metric
  ) {
    return (
      '<div class="insight-item">' +
        '<span class="insight-bullet"></span>' +

        '<div class="insight-copy">' +
          '<strong>' +
            escapeHtml(title) +
          '</strong>' +

          '<span>' +
            escapeHtml(description) +
          '</span>' +
        '</div>' +

        '<span class="insight-metric">' +
          escapeHtml(metric || '') +
        '</span>' +
      '</div>'
    );
  }


  function buildDrivers(
    overall,
    formats,
    platformRows,
    evidence,
    selectedPlatform
  ) {
    var drivers = [];

    var positiveFormats =
      formats
        .filter(function (row) {
          return (
            String(
              row.platform || ''
            ).toLowerCase() !==
              'all' &&
            toNumber(
              row.current_posts
            ) >= 2 &&
            toNumber(
              row.engagement_per_post_change_pct
            ) !== null &&
            toNumber(
              row.engagement_per_post_change_pct
            ) > 0
          );
        })
        .sort(
          function (a, b) {
            return (
              toNumber(
                b.engagement_per_post_change_pct
              ) -
              toNumber(
                a.engagement_per_post_change_pct
              )
            );
          }
        );

    if (
      positiveFormats.length > 0
    ) {
      var format =
        positiveFormats[0];

      var formatPosts =
        toNumber(
          format.current_posts
        ) || 0;

      drivers.push({
        title:
          (
            formatPosts <= 2
              ? 'Señal positiva preliminar: '
              : ''
          ) +
          formatLabel(
            format.post_type
          ) +
          ' en ' +
          platformLabel(
            format.platform
          ),

        description:
          formatPosts <= 2
            ? (
                'La mejora se observa en solo ' +
                formatInteger(
                  formatPosts
                ) +
                ' publicaciones. Es una señal para validar, no todavía un patrón consolidado.'
              )
            : (
                'El formato muestra una señal positiva frente a la ventana comparable.'
              ),

        metric:
          formatPct(
            format
              .engagement_per_post_change_pct
          )
      });
    }


    if (
      String(
        selectedPlatform || 'all'
      ).toLowerCase() ===
        'all' &&
      platformRows.length > 1
    ) {
      var shareRows =
        platformRows
          .filter(function (row) {
            return (
              toNumber(
                row.current_engagement_share_pct
              ) !== null
            );
          })
          .sort(
            function (a, b) {
              return (
                toNumber(
                  b.current_engagement_share_pct
                ) -
                toNumber(
                  a.current_engagement_share_pct
                )
              );
            }
          );

      if (
        shareRows.length > 0
      ) {
        var leadingPlatform =
          shareRows[0];

        drivers.push({
          title:
            (
              platformLabel(
                leadingPlatform.platform
              ) +
              ' concentra la actividad'
            ),

          description:
            'Aporta la mayor proporción del engagement comparable observado actualmente.',

          metric:
            (
              formatNumber(
                leadingPlatform
                  .current_engagement_share_pct,
                2
              ) +
              '%'
            )
        });
      }
    }


    if (overall) {
      var likesChange =
        toNumber(
          overall
            .likes_per_post_change_pct
        );

      if (
        likesChange !== null &&
        likesChange > 0
      ) {
        drivers.push({
          title:
            'Más likes por publicación',

          description:
            'La respuesta mediante likes por publicación supera la ventana comparable anterior.',

          metric:
            formatPct(
              likesChange
            )
        });
      }
    }


    var evidenceRows =
      evidence
        .filter(function (row) {
          return (
            toNumber(
              row.vs_platform_avg_pct
            ) !== null
          );
        })
        .sort(
          function (a, b) {
            return (
              toNumber(
                b.vs_platform_avg_pct
              ) -
              toNumber(
                a.vs_platform_avg_pct
              )
            );
          }
        );

    if (
      evidenceRows.length > 0
    ) {
      var bestPost =
        evidenceRows[0];

      drivers.push({
        title:
          (
            'Una publicación destaca en ' +
            platformLabel(
              bestPost.platform
            )
          ),

        description:
          shortText(
            bestPost.content_text,
            96
          ),

        metric:
          (
            formatPct(
              bestPost
                .vs_platform_avg_pct
            ) +
            ' vs promedio'
          )
      });
    }


    if (
      drivers.length === 0
    ) {
      drivers.push({
        title:
          'Sin señal positiva concluyente',

        description:
          'La ventana actual todavía no muestra una mejora consistente frente a la anterior.',

        metric:
          ''
      });
    }

    return drivers.slice(
      0,
      3
    );
  }


  function buildFrictions(
    overall,
    platformRows
  ) {
    var frictions = [];

    if (!overall) {
      return frictions;
    }

    var overallChange =
      toNumber(
        overall
          .engagement_per_post_change_pct
      );

    if (
      overallChange !== null &&
      overallChange < 0
    ) {
      frictions.push({
        title:
          'Menor engagement por publicación',

        description:
          'El promedio reciente de likes + comentarios por publicación está por debajo de la ventana anterior.',

        metric:
          formatPct(
            overallChange
          )
      });
    }


    var commentsChange =
      toNumber(
        overall
          .comments_per_post_change_pct
      );

    if (
      commentsChange !== null &&
      commentsChange < 0
    ) {
      frictions.push({
        title:
          'Menor nivel de comentarios',

        description:
          'Los comentarios por publicación muestran una reducción en la ventana comparable.',

        metric:
          formatPct(
            commentsChange
          )
      });
    }


    var decliningPlatforms =
      platformRows
        .filter(function (row) {
          var change =
            toNumber(
              row.engagement_per_post_change_pct
            );

          return (
            change !== null &&
            change < 0
          );
        })
        .sort(
          function (a, b) {
            return (
              toNumber(
                a.engagement_per_post_change_pct
              ) -
              toNumber(
                b.engagement_per_post_change_pct
              )
            );
          }
        );

    if (
      decliningPlatforms.length > 0
    ) {
      var weakest =
        decliningPlatforms[0];

      var duplicateOverall =
        platformRows.length === 1 &&
        overallChange !== null &&
        Math.abs(
          toNumber(
            weakest
              .engagement_per_post_change_pct
          ) -
          overallChange
        ) < 0.01;

      if (!duplicateOverall) {
        frictions.push({
          title:
            (
              platformLabel(
                weakest.platform
              ) +
              ' presenta la mayor caída'
            ),

          description:
            'Es la plataforma con la variación más negativa de engagement por publicación dentro de la comparación actual.',

          metric:
            formatPct(
              weakest
                .engagement_per_post_change_pct
            )
        });
      }
    }


    if (
      frictions.length === 0
    ) {
      frictions.push({
        title:
          'Sin deterioro relevante detectado',

        description:
          'Las señales comparables actuales no muestran una caída significativa.',

        metric:
          ''
      });
    }

    return frictions.slice(
      0,
      3
    );
  }


  function renderInsights(
    overall,
    formats,
    platformRows,
    evidence,
    selectedPlatform
  ) {
    var drivers =
      buildDrivers(
        overall,
        formats,
        platformRows,
        evidence,
        selectedPlatform
      );

    var frictions =
      buildFrictions(
        overall,
        platformRows
      );

    var driversElement =
      byId('driversList');

    var frictionsElement =
      byId('frictionsList');

    if (driversElement) {
      driversElement.innerHTML =
        drivers
          .map(function (item) {
            return insightItem(
              item.title,
              item.description,
              item.metric
            );
          })
          .join('');
    }

    if (frictionsElement) {
      frictionsElement.innerHTML =
        frictions
          .map(function (item) {
            return insightItem(
              item.title,
              item.description,
              item.metric
            );
          })
          .join('');
    }
  }


  function buildActions(
    overall,
    formats,
    platformRows,
    evidence
  ) {
    var actions = [];

    var overallChange =
      overall
        ? toNumber(
            overall
              .engagement_per_post_change_pct
          )
        : null;

    var commentsChange =
      overall
        ? toNumber(
            overall
              .comments_per_post_change_pct
          )
        : null;


    if (
      overallChange !== null &&
      overallChange < 0
    ) {
      actions.push({
        title:
          'Corregir la caída del engagement reciente',

        description:
          'Revisa qué cambió entre ambas ventanas en formatos, frecuencia y publicaciones con menor respuesta antes de incrementar volumen de contenido.',

        evidence:
          (
            'Engagement por publicación: ' +
            formatPct(
              overallChange
            )
          )
      });
    }


    var usefulFormats =
      formats
        .filter(function (row) {
          var change =
            toNumber(
              row.engagement_per_post_change_pct
            );

          return (
            String(
              row.platform || ''
            ).toLowerCase() !==
              'all' &&
            toNumber(
              row.current_posts
            ) >= 2 &&
            change !== null &&
            change > 0
          );
        })
        .sort(
          function (a, b) {
            return (
              toNumber(
                b.engagement_per_post_change_pct
              ) -
              toNumber(
                a.engagement_per_post_change_pct
              )
            );
          }
        );


    if (
      usefulFormats.length > 0 &&
      actions.length < 3
    ) {
      var format =
        usefulFormats[0];

      var currentFormatPosts =
        toNumber(
          format.current_posts
        ) || 0;

      if (
        currentFormatPosts <= 2
      ) {
        actions.push({
          title:
            (
              'Validar ' +
              formatLabel(
                format.post_type
              ) +
              ' en ' +
              platformLabel(
                format.platform
              )
            ),

          description:
            (
              'La señal es positiva, pero se basa en solo ' +
              formatInteger(
                currentFormatPosts
              ) +
              ' publicaciones. Prueba más contenido de este formato antes de aumentar su peso de forma sostenida.'
            ),

          evidence:
            (
              formatInteger(
                currentFormatPosts
              ) +
              ' publicaciones · ' +
              formatNumber(
                format
                  .current_engagement_per_post,
                2
              ) +
              ' engagement/post · ' +
              formatPct(
                format
                  .engagement_per_post_change_pct
              )
            )
        });

      } else {
        actions.push({
          title:
            (
              'Reforzar ' +
              formatLabel(
                format.post_type
              ) +
              ' en ' +
              platformLabel(
                format.platform
              )
            ),

          description:
            'El formato mejora frente a la ventana anterior. Mantén su presencia y prueba aumentar gradualmente su peso mientras verificas que la señal se sostenga.',

          evidence:
            (
              formatInteger(
                currentFormatPosts
              ) +
              ' publicaciones · ' +
              formatNumber(
                format
                  .current_engagement_per_post,
                2
              ) +
              ' engagement/post · ' +
              formatPct(
                format
                  .engagement_per_post_change_pct
              )
            )
        });
      }
    }


    var decliningPlatforms =
      platformRows
        .filter(function (row) {
          var change =
            toNumber(
              row.engagement_per_post_change_pct
            );

          return (
            change !== null &&
            change < 0
          );
        })
        .sort(
          function (a, b) {
            return (
              toNumber(
                a.engagement_per_post_change_pct
              ) -
              toNumber(
                b.engagement_per_post_change_pct
              )
            );
          }
        );


    if (
      decliningPlatforms.length > 0 &&
      actions.length < 3
    ) {
      var platform =
        decliningPlatforms[0];

      var duplicatesOverall =
        platformRows.length === 1 &&
        overallChange !== null &&
        Math.abs(
          toNumber(
            platform
              .engagement_per_post_change_pct
          ) -
          overallChange
        ) < 0.01;

      if (!duplicatesOverall) {
        actions.push({
          title:
            (
              'Auditar ' +
              platformLabel(
                platform.platform
              )
            ),

          description:
            'Es la plataforma con mayor deterioro de engagement por publicación. Revisa sus publicaciones recientes para localizar el contenido que está arrastrando el promedio.',

          evidence:
            (
              'Variación del engagement/post: ' +
              formatPct(
                platform
                  .engagement_per_post_change_pct
              )
            )
        });
      }
    }


    if (
      commentsChange !== null &&
      commentsChange < 0 &&
      actions.length < 3
    ) {
      actions.push({
        title:
          'Estimular más conversación',

        description:
          'Los comentarios por publicación están cayendo. Prueba llamados explícitos a responder, preguntas concretas y contenidos que inviten a compartir experiencias u opiniones.',

        evidence:
          (
            'Comentarios por publicación: ' +
            formatPct(
              commentsChange
            )
          )
      });
    }


    if (
      evidence.length > 0 &&
      actions.length < 3
    ) {
      var bestEvidence =
        evidence
          .slice()
          .sort(
            function (a, b) {
              return (
                (
                  toNumber(
                    b.vs_platform_avg_pct
                  ) || 0
                ) -
                (
                  toNumber(
                    a.vs_platform_avg_pct
                  ) || 0
                )
              );
            }
          )[0];

      actions.push({
        title:
          'Replicar los rasgos del contenido que sobresale',

        description:
          'Examina tema, enfoque, formato y estructura de la publicación líder y prueba variantes similares para comprobar si el patrón puede repetirse.',

        evidence:
          bestEvidence
            ? (
                platformLabel(
                  bestEvidence.platform
                ) +
                ': ' +
                formatPct(
                  bestEvidence
                    .vs_platform_avg_pct
                ) +
                ' frente al promedio'
              )
            : (
                formatInteger(
                  evidence.length
                ) +
                ' publicaciones destacadas disponibles'
              )
      });
    }


    while (
      actions.length < 3
    ) {
      actions.push({
        title:
          'Seguir acumulando evidencia comparable',

        description:
          'Mantén la observación antes de convertir una señal aislada en una conclusión estable.',

        evidence:
          'Comparación basada en likes + comentarios'
      });
    }

    return actions.slice(
      0,
      3
    );
  }


  function renderActions(
    overall,
    formats,
    platformRows,
    evidence
  ) {
    var element =
      byId('actionsList');

    if (!element) {
      return;
    }

    var actions =
      buildActions(
        overall,
        formats,
        platformRows,
        evidence
      );

    element.innerHTML =
      actions
        .map(
          function (
            action,
            index
          ) {
            return (
              '<article class="action-card">' +

                '<span class="action-number">' +
                  escapeHtml(
                    index + 1
                  ) +
                '</span>' +

                '<h3>' +
                  escapeHtml(
                    action.title
                  ) +
                '</h3>' +

                '<p>' +
                  escapeHtml(
                    action.description
                  ) +
                '</p>' +

                '<div class="action-evidence">' +
                  '<strong>Evidencia: </strong>' +
                  escapeHtml(
                    action.evidence
                  ) +
                '</div>' +

              '</article>'
            );
          }
        )
        .join('');
  }


  function renderPlatforms(
    platformRows
  ) {
    var element =
      byId('platformCards');

    if (!element) {
      return;
    }

    var rows =
      platformRows
        .slice()
        .sort(
          function (a, b) {
            var rankA =
              toNumber(
                a.engagement_per_post_rank
              );

            var rankB =
              toNumber(
                b.engagement_per_post_rank
              );

            if (
              rankA === null
            ) {
              rankA = 999;
            }

            if (
              rankB === null
            ) {
              rankB = 999;
            }

            return rankA - rankB;
          }
        );

    if (
      rows.length === 0
    ) {
      element.innerHTML =
        (
          '<article class="platform-card">' +
            '<span class="platform-name">' +
              'Sin datos comparables' +
            '</span>' +
          '</article>'
        );

      return;
    }

    element.innerHTML =
      rows
        .map(function (row) {
          var change =
            toNumber(
              row
                .engagement_per_post_change_pct
            );

          var rank =
            toNumber(
              row
                .engagement_per_post_rank
            );

          return (
            '<article class="platform-card">' +

              '<div class="platform-card-head">' +

                '<span class="platform-name">' +
                  escapeHtml(
                    platformLabel(
                      row.platform
                    )
                  ) +
                '</span>' +

                (
                  rank !== null
                    ? (
                        '<span class="platform-rank">' +
                          '#' +
                          escapeHtml(rank) +
                          ' por engagement/post' +
                        '</span>'
                      )
                    : ''
                ) +

              '</div>' +

              '<div class="platform-primary">' +

                '<strong>' +
                  escapeHtml(
                    formatNumber(
                      row
                        .current_engagement_per_post,
                      2
                    )
                  ) +
                '</strong>' +

                '<span>' +
                  'engagement / post' +
                '</span>' +

              '</div>' +

              '<div class="platform-change ' +
                escapeHtml(
                  trendClass(change)
                ) +
              '">' +

                escapeHtml(
                  formatPct(change)
                ) +

                ' vs ventana anterior' +

              '</div>' +

              '<div class="platform-meta">' +

                '<div>' +
                  '<span>Aporte actual</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatNumber(
                        row
                          .current_engagement_share_pct,
                        2
                      )
                    ) +
                    '%' +
                  '</strong>' +
                '</div>' +

                '<div>' +
                  '<span>Publicaciones</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatInteger(
                        row.current_posts
                      )
                    ) +
                  '</strong>' +
                '</div>' +

                '<div>' +
                  '<span>Likes / post</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatNumber(
                        row
                          .current_likes_per_post,
                        2
                      )
                    ) +
                  '</strong>' +
                '</div>' +

                '<div>' +
                  '<span>Comentarios / post</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatNumber(
                        row
                          .current_comments_per_post,
                        2
                      )
                    ) +
                  '</strong>' +
                '</div>' +

              '</div>' +

            '</article>'
          );
        })
        .join('');
  }


  function renderFormats(
    formats
  ) {
    var element =
      byId('formatCards');

    if (!element) {
      return;
    }

    var specificRows =
      formats
        .filter(function (row) {
          return (
            String(
              row.platform || ''
            ).toLowerCase() !==
              'all' &&
            toNumber(
              row.current_posts
            ) > 0
          );
        });

    var rows =
      specificRows.length > 0
        ? specificRows
        : formats.filter(
            function (row) {
              return (
                toNumber(
                  row.current_posts
                ) > 0
              );
            }
          );

    rows =
      rows
        .slice()
        .sort(
          function (a, b) {
            return (
              (
                toNumber(
                  b.current_engagement_per_post
                ) || 0
              ) -
              (
                toNumber(
                  a.current_engagement_per_post
                ) || 0
              )
            );
          }
        )
        .slice(
          0,
          6
        );

    if (
      rows.length === 0
    ) {
      element.innerHTML =
        (
          '<article class="format-card">' +
            '<span class="format-name">' +
              'Sin formatos comparables' +
            '</span>' +
          '</article>'
        );

      return;
    }

    element.innerHTML =
      rows
        .map(function (row) {
          return (
            '<article class="format-card">' +

              '<div class="format-card-head">' +

                '<span class="format-name">' +
                  escapeHtml(
                    formatLabel(
                      row.post_type
                    )
                  ) +
                '</span>' +

                '<span class="format-platform">' +
                  escapeHtml(
                    platformLabel(
                      row.platform
                    )
                  ) +
                '</span>' +

              '</div>' +

              '<div class="format-value">' +
                escapeHtml(
                  formatNumber(
                    row
                      .current_engagement_per_post,
                    2
                  )
                ) +
              '</div>' +

              '<span class="format-caption">' +
                'engagement por publicación' +
              '</span>' +

              '<div class="format-bottom">' +

                '<div class="format-share">' +
                  '<span>Aporte</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatNumber(
                        row
                          .current_engagement_share_pct,
                        2
                      )
                    ) +
                    '%' +
                  '</strong>' +
                '</div>' +

                '<div class="format-trend">' +
                  '<span>Variación</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatPct(
                        row
                          .engagement_per_post_change_pct
                      )
                    ) +
                  '</strong>' +
                '</div>' +

              '</div>' +

            '</article>'
          );
        })
        .join('');
  }


  function renderEvidence(
    evidence
  ) {
    var element =
      byId('evidenceCards');

    if (!element) {
      return;
    }

    var rows =
      evidence
        .slice()
        .sort(
          function (a, b) {
            var platformCompare =
              String(
                a.platform || ''
              ).localeCompare(
                String(
                  b.platform || ''
                )
              );

            if (
              platformCompare !== 0
            ) {
              return platformCompare;
            }

            return (
              (
                toNumber(
                  a.platform_rank
                ) || 999
              ) -
              (
                toNumber(
                  b.platform_rank
                ) || 999
              )
            );
          }
        );

    if (
      rows.length === 0
    ) {
      element.innerHTML =
        (
          '<article class="evidence-card">' +
            '<span class="evidence-platform">' +
              'Sin evidencia disponible' +
            '</span>' +
          '</article>'
        );

      return;
    }

    element.innerHTML =
      rows
        .map(function (row) {
          var url =
            String(
              row.post_url || ''
            ).trim();

          var link =
            url
              ? (
                  '<a' +
                    ' class="evidence-link"' +
                    ' href="' +
                      escapeHtml(url) +
                    '"' +
                    ' target="_blank"' +
                    ' rel="noopener noreferrer"' +
                  '>' +
                    'Ver publicación ↗' +
                  '</a>'
                )
              : '';

          return (
            '<article class="evidence-card">' +

              '<div class="evidence-head">' +

                '<span class="evidence-platform">' +
                  escapeHtml(
                    platformLabel(
                      row.platform
                    )
                  ) +
                '</span>' +

                '<span class="evidence-rank">' +
                  '#' +
                  escapeHtml(
                    row.platform_rank
                  ) +
                  ' de la plataforma' +
                '</span>' +

              '</div>' +

              '<span class="evidence-format">' +
                escapeHtml(
                  formatLabel(
                    row.post_type
                  )
                ) +
              '</span>' +

              '<p class="evidence-copy">' +
                escapeHtml(
                  shortText(
                    row.content_text,
                    220
                  )
                ) +
              '</p>' +

              '<div class="evidence-metrics">' +

                '<div class="evidence-metric">' +
                  '<span>Engagement</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatInteger(
                        row.engagement
                      )
                    ) +
                  '</strong>' +
                '</div>' +

                '<div class="evidence-metric">' +
                  '<span>Likes</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatInteger(
                        row.likes_count
                      )
                    ) +
                  '</strong>' +
                '</div>' +

                '<div class="evidence-metric">' +
                  '<span>Vs promedio</span>' +
                  '<strong>' +
                    escapeHtml(
                      formatPct(
                        row
                          .vs_platform_avg_pct
                      )
                    ) +
                  '</strong>' +
                '</div>' +

              '</div>' +

              link +

            '</article>'
          );
        })
        .join('');
  }


  function renderGeneratedAt(
    generatedAt
  ) {
    if (!generatedAt) {
      setText(
        'generatedAt',
        '—'
      );

      return;
    }

    var date =
      new Date(
        generatedAt
      );

    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      setText(
        'generatedAt',
        '—'
      );

      return;
    }

    setText(
      'generatedAt',
      (
        'Actualizado: ' +
        date.toLocaleString(
          'es-MX',
          {
            dateStyle: 'short',
            timeStyle: 'short'
          }
        )
      )
    );
  }


  function syncControls(model) {
    var period =
      byId('periodSelect');

    var platform =
      byId('platformSelect');

    if (period) {
      period.value =
        String(
          model &&
          model.periodDays
            ? model.periodDays
            : 30
        );
    }

    if (platform) {
      platform.value =
        String(
          model &&
          model.platform
            ? model.platform
            : 'all'
        );
    }

    renderQuerySelect(model);
  }


  function render(model) {
    model =
      model || {};

    syncControls(model);

    var runtime =
      getRuntime(model);

    var meta =
      runtime.meta || {};

    if (
      meta.loading === true
    ) {
      setLoading();
      return;
    }

    if (
      meta.error
    ) {
      setError(
        meta.error
      );
      return;
    }

    if (
      meta.empty === true ||
      runtime.palancas.length === 0
    ) {
      setEmpty();
      return;
    }

    var overall =
      findOverall(
        runtime.palancas
      );

    if (!overall) {
      setEmpty();
      return;
    }

    var platformRows =
      getPlatformRows(
        runtime.palancas
      );

    var selectedPlatform =
      String(
        model.platform || 'all'
      ).toLowerCase();

    setReady();

    buildStatus(
      overall,
      platformRows
    );

    renderInsights(
      overall,
      runtime.formatos,
      platformRows,
      runtime.evidencias,
      selectedPlatform
    );

    renderActions(
      overall,
      runtime.formatos,
      platformRows,
      runtime.evidencias
    );

    renderPlatforms(
      platformRows
    );

    renderFormats(
      runtime.formatos
    );

    renderEvidence(
      runtime.evidencias
    );

    renderGeneratedAt(
      meta.generatedAt
    );
  }


  async function requestReload(
    modelChanges
  ) {
    try {
      setLoading();

      var changes =
        modelChanges || {};

      if (
        Object.keys(
          changes
        ).length > 0
      ) {
        await appsmith.updateModel(
          changes
        );
      }

      appsmith.triggerEvent(
        'onRefresh'
      );

    } catch (error) {
      setError(
        error &&
        error.message
          ? error.message
          : String(error)
      );
    }
  }


  function bindEvents() {
    if (initialized) {
      return;
    }

    initialized = true;

    var period =
      byId('periodSelect');

    var platform =
      byId('platformSelect');

    var query =
      byId('querySelect');

    var refresh =
      byId('refreshButton');


    if (period) {
      period.addEventListener(
        'change',
        function (event) {
          requestReload({
            periodDays:
              Number(
                event.target.value
              )
          });
        }
      );
    }


    if (platform) {
      platform.addEventListener(
        'change',
        function (event) {
          requestReload({
            platform:
              String(
                event.target.value
              )
          });
        }
      );
    }


    if (query) {
      query.addEventListener(
        'change',
        function (event) {
          var selectedId =
            String(
              event.target.value || ''
            ).trim();

          var selectedOption =
            event.target
              .options[
                event.target
                  .selectedIndex
              ];

          var selectedName =
            selectedOption
              ? String(
                  selectedOption
                    .textContent || ''
                ).trim()
              : '';

          if (!selectedId) {
            return;
          }

          requestReload({
            selectedQueryId:
              selectedId,

            selectedQueryName:
              selectedName
          });
        }
      );
    }


    if (refresh) {
      refresh.addEventListener(
        'click',
        function () {
          requestReload({});
        }
      );
    }
  }


  bindEvents();

  render(
    appsmith.model || {}
  );


  appsmith.onModelChange(
    function (newModel) {
      render(
        newModel || {}
      );
    }
  );

});
